import type { CSSObject, Theme } from "@emotion/react";
import type { MenuItemProps } from "./menu-item.types";
import type { ComponentStyleVariantConfig } from "@types";

import styled from "@emotion/styled";
import { getStyleSlots, getExcludedDOMProps } from "@system";
import { useMemo } from "react";

// Make sure component name matches its type in the ThemeComponentVariants
const componentName = "MenuItem";

// Generate child element class names for the component, should match available style slots
export const MenuItemClasses = {
  root: "exp-textura_menu-item",
  label: "exp-textura_menu-item_label",
  text: "exp-textura_menu-item_text",
  subtext: "exp-textura_menu-item_subtext",
  hotkey: "exp-textura_menu-item_hotkey",
  leadingIcon: "exp-textura_menu-item_leading_icon",
  trailingIcon: "exp-textura_menu-item_trailing_icon",
  sm: "exp-textura_menu-item_sm",
};

// Set up style variant settings for the component (if more than "default"), using style slots
const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
  destructive: {
    root: {
      color: theme.menu.destructive.color.content.enabled,
    },
    hover: {
      backgroundColor: theme.menu.destructive.color.background.hover,
      color: theme.menu.destructive.color.content.hover,
    },
    pressed: {
      backgroundColor: theme.menu.destructive.color.background.pressed,
      color: theme.menu.destructive.color.content.pressed,
    },
    selected: {
      backgroundColor: theme.menu.destructive.color.background.selected,
      color: theme.menu.destructive.color.content.selected,
    },
    disabled: {
      color: theme.menu.destructive.color.content.disabled,
    },
    leadingIcon: {
      color: theme.color.content.utility.critical,
    },
    leadingIconHover: {
      color: theme.color.content.utility.criticalStrong,
    },
    leadingIconPressed: {
      color: theme.color.content.inverse,
    },
    leadingIconSelected: {
      color: theme.color.content.utility.criticalStrong,
    },
    leadingIconDisabled: {
      color: theme.color.content.utility.criticalWeak,
    },
    trailingIcon: {
      color: theme.color.content.utility.critical,
    },
    trailingIconHover: {
      color: theme.color.content.utility.criticalStrong,
    },
    trailingIconSelected: {
      color: theme.color.neutral.black,
    },
    subtext: {
      color: theme.color.content.weak,
    },
    subtextHover: {
      color: theme.color.content.utility.criticalStrong,
    },
    subtextPressed: {
      color: theme.color.content.inverse,
    },
    subtextSelected: {
      color: theme.color.content.strong,
    },
    hotkey: {
      color: theme.color.content.weak,
    },
    hotkeyHover: {
      color: theme.color.content.utility.criticalStrong,
    },
    hotkeyPressed: {
      color: theme.color.content.inverse,
    },
    hotkeySelected: {
      color: theme.color.content.strong,
    },
  },
  "icons-only": {
    root: {
      color: undefined,
    },
  },
});

const generateStyles = ({
  theme,
  variant,
  styleSlots: styleSlotsProp,
}: {
  theme: Theme;
  variant: MenuItemProps["variant"];
  styleSlots: MenuItemProps["styleSlots"];
}): CSSObject => {
  if (!theme?.menu) return {};
  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<MenuItemProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        getVariantConfig(theme),
      ),
    [theme, variant, styleSlotsProp],
  );

  return {
    [`&.${MenuItemClasses.root}`]: {
      boxSizing: "border-box",
      display: "flex",
      alignItems: "center",
      justifyContent: "space-between",
      width: "100%",
      userSelect: "none",
      textDecoration: "none",
      borderRadius: theme.toRem(theme.border.radius.sm),
      ...theme.typography.body.md,
      gap: theme.toRem(theme.spacing[8]),
      color: theme.menu.default.color.content.enabled,
      position: "relative",
      cursor: "pointer",
      minHeight: theme.toRem(32),
      padding: `${theme.toRem(theme.spacing[4])} ${theme.toRem(theme.spacing[8])}`,

      "&[data-has-subtext]": {
        alignItems: "flex-start",
        [`& .${MenuItemClasses.leadingIcon}`]: {
          height: theme.typography.body.md.lineHeight,
        },
        [`& .${MenuItemClasses.trailingIcon}`]: {
          height: theme.typography.body.md.lineHeight,
        },
        [`& .${MenuItemClasses.hotkey}`]: {
          height: theme.typography.body.md.lineHeight,
          display: "flex",
          alignItems: "center",
        },
      },

      "&:focus-visible": {
        boxShadow: "none !important",
      },

      "svg:last-child": {
        marginInlineStart: "auto",
      },

      "&[data-highlighted]": {
        backgroundColor: theme.menu.default.color.background.hover,
        color: theme.menu.default.color.content.hover,
        textDecoration: "none",
        outline: "none",
        boxShadow: "none",
        "&:hover:not(:active)": {
          textDecoration: "none",
        },
        [`& .${MenuItemClasses.hotkey}`]: {
          color: theme.color.content.default,
          ...styleSlots?.hotkeyHover,
        },
        [`& .${MenuItemClasses.subtext}`]: {
          color: theme.color.content.default,
          ...styleSlots?.subtextHover,
        },
        [`& .${MenuItemClasses.leadingIcon}`]: {
          color: theme.color.content.iconStrong,
          ...styleSlots?.leadingIconHover,
        },
        [`& .${MenuItemClasses.trailingIcon}`]: {
          color: theme.color.content.iconStrong,
          ...styleSlots?.trailingIconHover,
        },
        ...styleSlots?.hover,
      },

      "&[data-disabled]": {
        color: theme.menu.default.color.content.disabled,
        pointerEvents: "none",
        [`& .${MenuItemClasses.hotkey}`]: {
          color: theme.color.content.disabled,
          ...styleSlots?.hotkeyDisabled,
        },
        [`& .${MenuItemClasses.subtext}`]: {
          color: theme.color.content.disabled,
          ...styleSlots?.subtextDisabled,
        },
        [`& .${MenuItemClasses.leadingIcon}`]: {
          color: theme.color.content.disabled,
          ...styleSlots?.leadingIconDisabled,
        },
        [`& .${MenuItemClasses.trailingIcon}`]: {
          color: theme.color.content.disabled,
          ...styleSlots?.trailingIconDisabled,
        },
        ...styleSlots?.disabled,
      },

      "&:active": {
        backgroundColor: theme.menu.default.color.background.pressed,
        color: theme.menu.default.color.content.pressed,
        [`& .${MenuItemClasses.hotkey}`]: {
          color: theme.color.content.inverse,
          ...styleSlots?.hotkeypressed,
        },
        [`& .${MenuItemClasses.subtext}`]: {
          color: theme.color.content.inverse,
          ...styleSlots?.subtextPressed,
        },
        [`& .${MenuItemClasses.leadingIcon}`]: {
          color: theme.color.content.inverse,
          ...styleSlots?.leadingIconPressed,
        },
        [`& .${MenuItemClasses.trailingIcon}`]: {
          color: theme.color.content.inverseStrong,
          ...styleSlots?.trailingIconPressed,
        },
        ...styleSlots?.pressed,
      },

      '&[data-state=open]:not(:hover), &[data-selected="true"]:not(:hover)': {
        backgroundColor: theme.menu.default.color.background.selected,
        color: theme.menu.default.color.content.selected,
        [`& .${MenuItemClasses.hotkey}`]: {
          color: "inherit",
          ...styleSlots?.hotkeySelected,
        },
        [`& .${MenuItemClasses.subtext}`]: {
          color: "inherit",
          ...styleSlots?.subtextSelected,
        },
        [`& .${MenuItemClasses.leadingIcon}`]: {
          color: theme.color.content.actionSelected,
          ...styleSlots?.leadingIconSelected,
        },
        [`& .${MenuItemClasses.trailingIcon}`]: {
          color: theme.color.content.actionSelected,
          ...styleSlots?.trailingIconSelected,
        },
        ...styleSlots?.selected,
      },

      [`& .${MenuItemClasses.leadingIcon}`]: {
        display: "flex",
        alignItems: "center",
        color: theme.color.content.icon,
        "& > svg": {
          width: theme.toRem(16),
          height: theme.toRem(16),
          color: "inherit",
        },
        ...styleSlots?.leadingIcon,
      },

      [`& .${MenuItemClasses.trailingIcon}`]: {
        display: "flex",
        alignItems: "center",
        color: theme.color.content.icon,
        "& > svg": {
          width: theme.toRem(16),
          height: theme.toRem(16),
          color: "inherit",
        },
        ...styleSlots?.trailingIcon,
      },

      [`& .${MenuItemClasses.label}`]: {
        flex: "1 1 auto",
        ...styleSlots?.label,
        ...theme.typography.body.md,
      },

      [`& .${MenuItemClasses.text}`]: {
        display: "flex",
        flexDirection: "column",
        flex: "1 1 auto",
        ...styleSlots?.text,
      },

      [`& .${MenuItemClasses.subtext}`]: {
        ...theme.typography.body.sm,
        lineHeight: theme.typography.lineHeight[16],
        color: theme.color.content.weak,
        ...styleSlots?.subtext,
      },

      [`& .${MenuItemClasses.hotkey}`]: {
        ...theme.typography.body.sm,
        color: theme.color.content.weak,
        ...styleSlots?.hotkey,
      },

      [`&.${MenuItemClasses.sm}`]: {
        minHeight: theme.toRem(24),
        padding: `${theme.toRem(theme.spacing[4])} ${theme.toRem(theme.spacing[12])}`,
        ...theme.typography.body.sm,
        gap: theme.toRem(theme.spacing[8]),
        [`.${MenuItemClasses.label}`]: {
          ...theme.typography.body.sm,
        },
        [`& .${MenuItemClasses.leadingIcon}`]: {
          "& > svg": {
            width: theme.toRem(12),
            height: theme.toRem(12),
          },
        },
        [`& .${MenuItemClasses.trailingIcon}`]: {
          "& > svg": {
            width: theme.toRem(12),
            height: theme.toRem(12),
          },
        },
        ...styleSlots?.sm,
      },

      ...styleSlots?.root,
    },
  };
};

// Certain props passed to styled components should not be passed to the DOM element
const excludedDOMProps = getExcludedDOMProps();

// Define the styled component, exclude props from the DOM, generate themed JSS
export const StyledMenuItem = styled("div", {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<MenuItemProps>(({ theme, variant = "default", styleSlots }) =>
  generateStyles({ theme, variant, styleSlots }),
);
